 private static void helpers(ClassBuilder b,ClassDesc own){int flags=ClassFile.ACC_PRIVATE|ClassFile.ACC_STATIC|ClassFile.ACC_SYNTHETIC;b.withMethodBody(VIOLATION,MethodTypeDesc.of(CD_void,CD_int),flags,c->{var done=c.newLabel();c.iload(0).ifne(done);guard(c,own,()->c.invokestatic(REPORT,"failed",MethodTypeDesc.of(CD_void)));c.labelBinding(done).return_();});b.withMethodBody(ENTRY,MethodTypeDesc.of(CD_int),flags,c->{int result=c.allocateLocal(TypeKind.INT);c.iconst_m1().istore(result);guard(c,own,()->c.invokestatic(GATE,"enter",MethodTypeDesc.of(CD_int)).istore(result));c.iload(result).ireturn();});b.withMethodBody(LEAVE,MethodTypeDesc.of(CD_void,CD_int),flags,c->{var done=c.newLabel();c.iload(0).ifle(done);guard(c,own,()->c.iload(0).invokestatic(GATE,"leave",MethodTypeDesc.of(CD_void,CD_int)));c.labelBinding(done).return_();});}
